<template><section class="report-evidence"><button type="button" class="outlined" :disabled="loading" @click="load">{{loading?'불러오는 중…':'신고 대화 확인'}}</button><p v-if="loaded">선택된 메시지와 앞뒤 대화입니다. 선택 없는 신고는 접수 전 최근 100개를 표시합니다.</p><p v-if="loaded&&!rows.length">확인할 대화가 없습니다.</p><article v-for="m in rows" :key="m.id" :class="{selected:m.selected}"><strong>{{m.senderId===targetId?'신고 대상':'신고자'}} <span v-if="m.selected">· 신고한 메시지</span></strong><p>{{m.text}}</p><small>{{new Date(m.createdAt).toLocaleString('ko-KR')}}</small></article><p v-if="error" role="alert">{{error}}</p></section></template>
<script setup>import {ref,watch} from 'vue';import api from '../api/api';const props=defineProps({reportId:Number,targetId:Number});const rows=ref([]),loading=ref(false),loaded=ref(false),error=ref('');watch(()=>props.reportId,()=>{rows.value=[];loaded.value=false;error.value='';});async function load(){loading.value=true;error.value='';const id=props.reportId;try{const {data}=await api.get(`/admin/safety/reports/${id}/conversation`);if(id===props.reportId){rows.value=data;loaded.value=true;}}catch(e){error.value=e.response?.data?.message||'대화를 불러오지 못했습니다.';}finally{loading.value=false;}}</script>
<style scoped>.report-evidence{margin:18px 0;max-height:400px;overflow:auto}.report-evidence>p{font-size:12px;color:#777}.report-evidence article{padding:12px;margin:8px 0;border:1px solid #eee;border-radius:10px;font-size:12px}.report-evidence article.selected{background:#fff0e6;border-color:#d4815e}.report-evidence article p{white-space:pre-wrap;overflow-wrap:anywhere}.report-evidence small{color:#999}</style>
